<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Ubuntu Desktop</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: Ubuntu, system-ui, -apple-system, sans-serif;
      background: #2c001e;
      height: 100vh;
      overflow: hidden;
      color: #fff;
    }
    #desktop {
      position: absolute;
      top: 0; left: 0; width: 100vw; height: 100vh;
      background: radial-gradient(circle at center, #3b2835 0%, #1a0000 100%);
      overflow: hidden;
    }
    #taskbar {
      position: fixed; bottom: 0; left: 0; width: 100%;
      height: 50px;
      background: rgba(0,0,0,0.7);
      border-top: 1px solid #444;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      z-index: 1000;
    }
    .launcher-btn {
      background: #333;
      border: 1px solid #555;
      color: #fff;
      padding: 6px 16px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 14px;
    }
    .launcher-btn:hover { background: #555; }
    .window {
      position: absolute;
      background: #333;
      border: 1px solid #000;
      border-radius: 8px;
      box-shadow: 0 8px 16px rgba(0,0,0,0.5);
      display: flex; flex-direction: column;
      min-width: 360px; min-height: 240px;
      overflow: hidden;
    }
    .win-header {
      background: #222;
      padding: 6px 12px;
      display: flex; justify-content: space-between; align-items: center;
      cursor: default;
    }
    .win-title { font-size: 14px; font-weight: bold; }
    .win-close {
      background: #d32f2f;
      border: none; color: white;
      width: 14px; height: 14px;
      border-radius: 50%;
      cursor: pointer;
      font-size: 10px; line-height: 14px; text-align: center;
    }
    .win-content { flex: 1; padding: 0px; overflow: auto; background: #2b2b2b; }

    /* Files App */
    .path-bar { display: flex; gap: 5px; margin-bottom: 8px; }
    #files-path {
      flex: 1; background: #111; border: 1px solid #444;
      color: #ddd; padding: 4px 8px; border-radius: 3px;
      font-size: 13px; font-family: monospace;
    }
    #files-up {
      background: #444; border: 1px solid #555; color: white;
      cursor: pointer; width: 24px;
    }
    .fs-list { display: flex; flex-wrap: wrap; gap: 8px; }
    .fs-item {
      background: #3a3a3a;
      border: 1px solid #444;
      padding: 6px 10px;
      border-radius: 4px;
      cursor: default;
      font-size: 14px;
    }
    .fs-item:hover { background: #4a4a4a; }
    .fs-item.folder { color: #ffb86c; }

    /* Notepad App */
    .tabs-bar { display: flex; background: #222; padding: 4px 4px 0 4px; gap: 2px; }
    #tabs { display: flex; flex: 1; gap: 2px; }
    .tab {
      background: #333; color: #aaa;
      padding: 5px 12px; border-radius: 4px 4px 0 0;
      font-size: 12px; cursor: pointer;
    }
    .tab.active { background: #3a3a3a; color: #fff; font-weight: bold; }
    #new-tab {
      background: #444; border: 1px solid #555; color: white;
      font-size: 16px; line-height: 1;
      width: 28px; height: 22px;
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; border-radius: 4px;
      flex-shrink: 0; margin-left: auto;
    }
    #editor {
      width: 100%; height: 100%; border: none;
      background: #1e1e1e; color: #ddd;
      padding: 10px; font-family: monospace; font-size: 14px;
      resize: none;
    }
  </style>
</head>
<body>

<div id="desktop">
  <div id="taskbar">
    <button id="open-files" class="launcher-btn">Files</button>
    <button id="open-notepad" class="launcher-btn">Notepad</button>
  </div>

  <!-- Files App Window -->
  <div id="files-window" class="window" style="display: none; top: 80px; left: 80px;">
    <div class="win-header">
      <span class="win-title">Files</span>
      <button class="win-close" title="Close">X</button>
    </div>
    <div class="win-content">
      <div class="path-bar">
        <div id="files-path">/</div>
        <button id="files-up">↑</button>
      </div>
      <div class="fs-list" id="fs-list"></div>
    </div>
  </div>

  <!-- Notepad App Window -->
  <div id="notepad-window" class="window" style="display: none; top: 120px; left: 120px;">
    <div class="win-header">
      <span class="win-title">Notepad</span>
      <button class="win-close" title="Close">X</button>
    </div>
    <div class="win-content" style="display: flex; flex-direction: column; padding: 0;">
      <div class="tabs-bar">
        <div id="tabs"></div>
        <button id="new-tab">+</button>
      </div>
      <textarea id="editor"></textarea>
    </div>
  </div>
</div>

<script>
/* --- Filesystem --- */
const fsData = {
  root: {
    children: {
      bin: { name: "bin", type: "dir" },
      etc: { name: "etc", type: "dir" },
      home: {
        name: "home", type: "dir",
        children: {
          user: {
            name: "user", type: "dir",
            children: {
              Documents: { name: "Documents", type: "dir" },
              Downloads: { name: "Downloads", type: "dir" },
              Pictures: { name: "Pictures", type: "dir" }
            }
          }
        }
      },
      usr: { name: "usr", type: "dir" },
      var: { name: "var", type: "dir" }
    }
  }
};

let currentPath = [

const fsPathEl = document.getElementById("files-path");
const fsListEl = document.getElementById("fs-list");
const fsUpBtn = document.getElementById("files-up");

function getCurrentFolder() {
  let curr = fsData.root;
  for (const part of currentPath) {
    if (curr.children && curr.children[part]) curr = curr.children[part];
    else return null;
  }
  return curr;
}

function renderFiles() {
  const pathStr = "/" + currentPath.join("/");
  fsPathEl.textContent = pathStr;
  fsListEl.innerHTML = "";
  const folder = getCurrentFolder();
  if (folder && folder.children) {
    const names = Object.keys(folder.children);
    names.forEach(name => {
      const el = document.createElement("div");
      el.className = "fs-item " + (folder.children[name].type === "dir" ? "folder" : "");
      el.textContent = name;
      el.addEventListener("dblclick", () => {
        if (folder.children[name].type === "dir") {
          currentPath.push(name);
          renderFiles();
        }
      });
      fsListEl.appendChild(el);
    });
  }
}

fsUpBtn.addEventListener("click", () => {
  if (currentPath.length > 0) {
    currentPath.pop();
    renderFiles();
  }
});

/* --- Notepad Persistence --- */
const tabsContainer = document.getElementById("tabs");
const newTabBtn = document.getElementById("new-tab");
const editor = document.getElementById("editor");
const STORAGE_KEY = "notepad_tabs";
let tabs = [];
let activeTabId = null;

function saveToStorage() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tabs));
}

function loadFromStorage() {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    try {
      tabs = JSON.parse(stored);
    } catch(e) {}
  } else {
    tabs = [{ id: Date.now(), name: "Tab 1", content: "" }];
  }
  if (tabs.length > 0 && !activeTabId) activeTabId = tabs[0].id;
  renderTabs();
}

function renderTabs() {
  tabsContainer.innerHTML = "";
  tabs.forEach(tab => {
    const el = document.createElement("div");
    el.className = "tab" + (tab.id === activeTabId ? " active" : "");
    el.textContent = tab.name;
    el.addEventListener("click", () => switchTab(tab.id));
    tabsContainer.appendChild(el);
  });
  if (activeTabId) {
    const tab = tabs.find(t => t.id === activeTabId);
    if (tab) editor.value = tab.content;
  }
}

function switchTab(id) {
  activeTabId = id;
  const tab = tabs.find(t => t.id === id);
  if (tab) editor.value = tab.content;
  renderTabs();
}

function addTab() {
  const newId = Date.now();
  tabs.push({ id: newId, name: `Tab ${tabs.length + 1}`, content: "" });
  activeTabId = newId;
  saveToStorage();
  renderTabs();
}

newTabBtn.addEventListener("click", addTab);
editor.addEventListener("input", () => {
  const tab = tabs.find(t => t.id === activeTabId);
  if (tab) {
    tab.content = editor.value;
    saveToStorage();
  }
});

/* --- Window Management --- */
const filesWin = document.getElementById("files-window");
const notepadWin = document.getElementById("notepad-window");
const openFilesBtn = document.getElementById("open-files");
const openNotepadBtn = document.getElementById("open-notepad");

function closeWindow(el) {
  el.style.display = "none";
}
function openWindow(el) {
  el.style.display = "flex";
}

openFilesBtn.addEventListener("click", () => openWindow(filesWin));
openNotepadBtn.addEventListener("click", () => openWindow(notepadWin));

document.querySelectorAll(".win-close").forEach(btn => {
  btn.addEventListener("click", (e) => {
    closeWindow(e.target.closest(".window"));
  });
});

/* --- Basic Dragging --- */
function makeDraggable(win) {
  const header = win.querySelector(".win-header");
  let isDragging = false;
  let startX, startY, origX, origY;

  header.addEventListener("mousedown", (e) => {
    isDragging = true;
    startX = e.clientX;
    startY = e.clientY;
    const rect = win.getBoundingClientRect();
    origX = rect.left;
    origY = rect.top;
  });

  document.addEventListener("mousemove", (e) => {
    if (!isDragging) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    win.style.left = (origX + dx) + "px";
    win.style.top = (origY + dy) + "px";
  });

  document.addEventListener("mouseup", () => { isDragging = false; });
}

makeDraggable(filesWin);
makeDraggable(notepadWin);

/* --- Init --- */
renderFiles();
loadFromStorage();
</script>
</body>
</html>
